    - regex: 'user_id|session'
      action: labeldrop

Checar cardinalidade atual:
topk(10, count by (__name__) ({__name__=~".+"}))

Cadeia: Nginx -> api-gateway (Node) -> pedidos-svc (Node) -> RabbitMQ -> pagamento-worker (Node) -> gateway externo.

Propagação HTTP: automática com @opentelemetry/instrumentation-http (injeta/extrai traceparent).

Propagação via RabbitMQ (manual ou com instrumentation-amqplib):
// produtor
const headers = {};
propagation.inject(context.active(), headers);
channel.publish(ex, key, body, { headers });

// consumidor
const parentCtx = propagation.extract(context.active(), msg.properties.headers);
const span = tracer.startSpan('processar-pagamento', { links: [{ context: trace.getSpanContext(parentCtx) }] }, parentCtx);

Resultado no Tempo: o trace do checkout mostra o span do worker 40s depois do span do produtor (tempo na fila visível!), e o span da chamada ao gateway externo com 8s — o culpado do checkout lento, num processo que nem recebe HTTP.

Nginx: opentracing/otel module ou, no mínimo, repassar o header traceparent sem alterar.

// tracing.js — carregado ANTES do app: node -r ./tracing.js app.js
const { NodeSDK } = require('@opentelemetry/sdk-node');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-grpc');
const { getNodeAutoInstrumentations } = require('@opentelemetry/auto-instrumentations-node');
const { ParentBasedSampler, TraceIdRatioBasedSampler } = require('@opentelemetry/sdk-trace-base');

new NodeSDK({
  serviceName: 'api-pedidos',
  traceExporter: new OTLPTraceExporter({ url: 'http://otel-collector:4317' }),
  sampler: new ParentBasedSampler({ root: new TraceIdRatioBasedSampler(0.1) }),
  instrumentations: [getNodeAutoInstrumentations({
    '@opentelemetry/instrumentation-fs': { enabled: false },
    '@opentelemetry/instrumentation-dns': { enabled: false },
    '@opentelemetry/instrumentation-pg': { enhancedDatabaseReporting: false }, // não captura valores de parâmetros
  })],
}).start();

// PM2: ecosystem.config.js -> node_args: '-r ./tracing.js'

Collector (otel-collector-config.yaml) recebe OTLP, faz tail_sampling (guarda 100% dos traces com erro ou > 2s, 5% do resto) e exporta para Tempo + métricas derivadas (spanmetrics) para o Prometheus. Trocar Tempo por Jaeger = mudar 3 linhas no collector, zero deploy de app.

Request chegando no pedidos-svc:
traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01
              ^^ ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ ^^^^^^^^^^^^^^^^ ^^
           versão        trace_id (mesmo em todos)   span pai      sampled

O span criado aqui terá parent=00f067aa0ba902b7 e um span_id novo; a chamada ao próximo serviço sai com traceparent: 00-4bf92f35...-<novo span_id>-01.

Log correlacionado sem esforço (pino + OTel):
const { trace, context } = require('@opentelemetry/api');
const log = pino({ mixin() {
  const sc = trace.getSpan(context.active())?.spanContext();
  return sc ? { trace_id: sc.traceId, span_id: sc.spanId } : {};
}});

No Grafana: do log (Loki) com trace_id -> botão para abrir o trace no Tempo -> do span lento -> logs daquele span. Ida e volta em 3 cliques.

Na borda, para não confiar no sampling de fora:
sampler: new ParentBasedSampler({ root: ratio(0.1), remoteParentSampled: ratio(0.1) })

let ready = false; let shuttingDown = false;

app.get('/live', (req, res) => {
  // só o processo: se chegou aqui, o event loop responde
  res.status(200).end();
});

app.get('/ready', async (req, res) => {
  if (!ready || shuttingDown) return res.status(503).end();
  try {
    await Promise.race([pool.query('SELECT 1'), timeout(500)]);
    res.status(200).end();
  } catch { res.status(503).end(); }  // PG fora: sai do balanceador, NÃO reinicia
});

// após warm-up
ready = true; process.send?.('ready');

// graceful shutdown
process.on('SIGTERM', async () => {
  shuttingDown = true;                       // /ready passa a dar 503
  await sleep(5000);                          // balanceador percebe e para de mandar
  server.close(async () => { await pool.end(); process.exit(0); });
  setTimeout(() => process.exit(1), 25000);   // teto duro
});

Nginx upstream: max_fails=2 fail_timeout=5s ou health_check (Plus). Redis de cache: NÃO entra no /ready — a app degrada sem ele.
